-- daytime-caffeine-sleep
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('2f0cc739-d18b-5ca3-9981-5971623614e9', 'daytime-caffeine-sleep', 'Caffeine three times a day, the last dose 8 hours before bed: what the sleep lab recorded', '10.1038/s41598-021-84088-x', 'Sleep', 'Twenty young men who drink caffeine every day took 150 mg three times a day, the last dose 8 hours before bed. Their measured sleep did not differ from their placebo nights. One thing in the brain recordings did.', 'free', '2026-11-12T00:00:00Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('2f0cc739-d18b-5ca3-9981-5971623614e9', '{"hook":[{"text":"The usual advice is to stop caffeine by noon.","refs":[]},{"text":"A sleep laboratory tested something closer to how people actually take it: morning, midday and mid-afternoon, every day.","refs":["schedule"]}],"populationPanel":[{"text":"Who was studied: twenty healthy men aged 18 to 35 who already had 300 to 600 mg of caffeine a day and slept well.","refs":["sample","who","good_sleepers"]},{"text":"Each man went through all three conditions in random order without knowing which capsules he was taking.","refs":["blind"]},{"text":"The result describes men like these.","refs":["lim_male"]},{"text":"It says nothing yet about women, older adults or people who rarely have caffeine.","refs":["lim_male","lim_young","not_after_abstinence"]}],"sections":[{"id":"did","heading":"What they did","paragraphs":[[{"text":"For 10 days at a time the men swallowed a capsule three times a day: 45, 255 and 475 minutes after waking.","refs":["schedule"]},{"text":"In one condition every capsule held 150 mg of caffeine.","refs":["dose"]},{"text":"In another, all were placebo.","refs":["dose"]},{"text":"In a third, caffeine was swapped for placebo near the end, to see what stopping does.","refs":["dose"]}],[{"text":"After 9 days they slept in the laboratory wired to an EEG, with bedtime falling 8 hours after the last caffeine capsule.","refs":["recording"]}]]},{"id":"found","heading":"What they found","paragraphs":[[{"text":"Total sleep time, the time taken to fall asleep and the share of each sleep stage did not differ between the caffeine nights and the placebo nights.","refs":["sleep_same"]},{"text":"The men''s own ratings of how they slept did not differ either.","refs":["quality_same"]},{"text":"The researchers had expected to see less deep sleep on caffeine and did not find it.","refs":["no_depth_change"]}]]},{"id":"lower-bound","heading":"How sure is that?","paragraphs":[[{"text":"Here the paper gives less than we would like.","refs":[]},{"text":"Its text reports these comparisons only as not statistically significant, with p above 0.05, and gives no effect size and no confidence interval.","refs":["sleep_same"]},{"text":"With twenty people, a real difference of a few minutes could sit inside that result unnoticed.","refs":["sample","lim_n"]},{"text":"Read it as: no large disruption was detected in this group.","refs":["sleep_same"]},{"text":"It is not proof that there is none.","refs":[]}]]},{"id":"missed","heading":"What most summaries miss","paragraphs":[[{"text":"One measure did change.","refs":[]},{"text":"During non-REM sleep, brain activity in the sigma band was lower on caffeine nights than on placebo nights.","refs":["sigma"]},{"text":"The authors read this as an early sign of withdrawal, already present 8 hours after the last dose.","refs":["sigma_meaning"]},{"text":"In other words, a daily habit may mean beginning a small withdrawal every night and undoing it with the first cup every morning.","refs":["daily_reverse"]}],[{"text":"A second detail comes from the nights at home: on caffeine, the men went to bed about 25 minutes later than on placebo.","refs":["later_bed"]}]]},{"id":"parallel","heading":"A related idea","paragraphs":[[{"text":"Tolerance ties this together.","refs":[]},{"text":"The authors cite earlier work in which a week of regular caffeine blunted its effect on sleep, even at high evening doses.","refs":["tolerance"]},{"text":"They also warn that the same morning cup could still disturb sleep in someone coming off several days without any.","refs":["not_after_abstinence"]},{"text":"The habit, not just the cup, shapes the night.","refs":[]}]]}],"limitations":[[{"text":"Only men took part, so the result may not hold for women.","refs":["lim_male"]}],[{"text":"All were aged 18 to 35.","refs":["who"]},{"text":"The authors note that middle-aged people are more vulnerable to what caffeine does to sleep.","refs":["lim_young"]}],[{"text":"Twenty participants is a small trial, and the text gives no effect sizes to show how small a difference it could have missed.","refs":["sample","lim_n"]}]],"primaryEstimate":"sleep_same","simulator":{"kind":"caffeine-timeline","params":{"doseMinutes":[{"n":45,"ref":"schedule"},{"n":255,"ref":"schedule"},{"n":475,"ref":"schedule"}],"doseMg":{"n":150,"ref":"dose"},"testedGapHours":{"n":8,"ref":"recording"},"withdrawalGapHours":{"n":15,"ref":"recording"},"hoursInBed":{"n":8,"ref":"regular"},"bedtimeDriftMinutes":{"n":25,"ref":"later_bed"},"findings":[{"id":"sleep_same","kind":"finding","label":"no significant difference from placebo (p > 0.05); the text reports no effect size","quote":"the analyses of the polysomnography (PSG) did not reveal significant differences in total sleep time (TST), sleep efficiency (SE), sleep latencies, or the relative amount of sleep stages among the three conditions (> 0.05)","finding":{"outcome":"Total sleep time, time to fall asleep and sleep stages","tier":"low"}},{"id":"quality_same","kind":"finding","label":"no significant difference between conditions (p > 0.05)","quote":"Analyses of subjective sleep quality assessed with the Leeds Sleep Evaluation Questionnaire (LSEQ) did not reveal significant differences among the three conditions in any of the four domains of sleep quality (> 0.05)","finding":{"outcome":"Self-rated sleep quality","tier":"low"}},{"id":"sigma","kind":"finding","label":"lower than placebo in both the caffeine and withdrawal conditions (p < 0.05)","quote":"power density was significantly reduced compared to placebo in the sigma range during both withdrawal","finding":{"outcome":"Sigma-band brain activity during non-REM sleep","tier":"low"}}],"outside":{"id":"evening","kind":"context","label":"What earlier work reports for caffeine taken in the evening","quote":"caffeine consumed in the evening hours prolongs sleep latency, reduces total sleep time (TST), shortens deep sleep"},"caveat":{"id":"not_after_abstinence","kind":"statement","label":"The result may not hold after several days without caffeine","quote":"Importantly, our findings do not preclude potential impairments of nighttime sleep after morning caffeine intake, if preceded by several days of abstinence from the stimulant."}}},"facts":{"blind":{"id":"blind","kind":"context","label":"Trial design","quote":"We employed a double-blind, randomized, crossover study including a caffeine, a withdrawal, and a placebo condition."},"daily_reverse":{"id":"daily_reverse","kind":"statement","label":"Habitual consumers may reverse overnight withdrawal with the first dose each day","quote":"This reduction might reflect withdrawal symptoms which chronic consumers reverse daily by the first caffeine dose."},"dose":{"id":"dose","kind":"context","label":"The three conditions and the dose","quote":"caffeine (3 × 150 mg caffeine daily), withdrawal (3 × 150 mg caffeine for 8 days, then switch to placebo), and placebo (3 × placebo daily)"},"good_sleepers":{"id":"good_sleepers","kind":"context","label":"Participants were good sleepers","quote":"all volunteers reported good sleep quality assessed with the Pittsburgh Sleep Quality Index (PSQI; score ≤ 5)"},"later_bed":{"id":"later_bed","kind":"statement","label":"Bedtime at home was later on caffeine","quote":"the ambulatory sleep episodes were on average around 25 min later as compared to placebo"},"lim_male":{"id":"lim_male","kind":"limitation","label":"Men only","quote":"only male volunteers were included which clearly reduces the generalizability of the findings"},"lim_n":{"id":"lim_n","kind":"limitation","label":"Small sample","quote":"Second, only a limited number of participants were studied."},"lim_young":{"id":"lim_young","kind":"limitation","label":"Only young adults","quote":"Thus, the present results cannot be generalized to other age groups such as to middle-aged consumers which are more vulnerable to the caffeine-induced effects on sleep."},"no_depth_change":{"id":"no_depth_change","kind":"statement","label":"The predicted loss of deep sleep was not found","quote":"Taken together, we could not confirm our assumption of a caffeine-induced reduction of sleep depth, neither in terms of shorter SWS nor in terms of reduced SWA in the caffeine compared to the placebo condition."},"not_after_abstinence":{"id":"not_after_abstinence","kind":"statement","label":"The result may not hold after several days without caffeine","quote":"Importantly, our findings do not preclude potential impairments of nighttime sleep after morning caffeine intake, if preceded by several days of abstinence from the stimulant."},"quality_same":{"id":"quality_same","kind":"finding","label":"no significant difference between conditions (p > 0.05)","quote":"Analyses of subjective sleep quality assessed with the Leeds Sleep Evaluation Questionnaire (LSEQ) did not reveal significant differences among the three conditions in any of the four domains of sleep quality (> 0.05)","finding":{"outcome":"Self-rated sleep quality","tier":"low"}},"recording":{"id":"recording","kind":"context","label":"When sleep was recorded relative to the last caffeine dose","quote":"After 9 days of continuous treatment, electroencephalographically (EEG)-derived sleep structure and intensity were recorded during a scheduled 8-h nighttime sleep episode starting 8 (caffeine condition) and 15 h (withdrawal condition) after the last caffeine intake."},"sample":{"id":"sample","kind":"context","label":"Number and sex of participants","quote":"Twenty male volunteers were recruited into the present study through online advertisements and flyers distributed in public areas."},"schedule":{"id":"schedule","kind":"context","label":"When the capsules were taken","quote":"three times daily, scheduled at 45 min, 255 min, and 475 min after awakening, for a duration of 10 days"},"sigma":{"id":"sigma","kind":"finding","label":"lower than placebo in both the caffeine and withdrawal conditions (p < 0.05)","quote":"power density was significantly reduced compared to placebo in the sigma range during both withdrawal","finding":{"outcome":"Sigma-band brain activity during non-REM sleep","tier":"low"}},"sigma_meaning":{"id":"sigma_meaning","kind":"statement","label":"Authors'' interpretation of the sigma change","quote":"These subtle alterations point to early signs of caffeine withdrawal in the homeostatic aspect of sleep-wake regulation which are already present as early as 8 h after the last caffeine intake."},"sleep_same":{"id":"sleep_same","kind":"finding","label":"no significant difference from placebo (p > 0.05); the text reports no effect size","quote":"the analyses of the polysomnography (PSG) did not reveal significant differences in total sleep time (TST), sleep efficiency (SE), sleep latencies, or the relative amount of sleep stages among the three conditions (> 0.05)","finding":{"outcome":"Total sleep time, time to fall asleep and sleep stages","tier":"low"}},"tolerance":{"id":"tolerance","kind":"context","label":"Earlier work on tolerance, cited by the authors","quote":"Accordingly, a 1-week treatment of caffeine reduced the sleep disrupting effects, even under conditions of high evening dosages."},"who":{"id":"who","kind":"context","label":"Age range and habitual caffeine intake","quote":"Interested individuals aged between 18 and 35 years old (mean age ± SD: 26.4 ± 4 years) and reporting a daily caffeine consumption between 300 and 600 mg (mean intake ± SD: 478.1 ± 102.8 mg) were included."}}}'::jsonb)
  on conflict (paper_id) do update set content_json = excluded.content_json, updated_at = now();
insert into public.paper_feature_content (paper_id, feature_key, payload) values ('2f0cc739-d18b-5ca3-9981-5971623614e9', 'key_takeaways', '{"takeaways":[[{"text":"The schedule tested was three doses, the last one 475 minutes after waking, which fell 8 hours before bed.","refs":["schedule","recording"]}],[{"text":"The finding covers a steady daily habit.","refs":["who"]},{"text":"The authors caution that it may not hold after several days without caffeine.","refs":["not_after_abstinence"]}],[{"text":"Bedtime at home drifted about 25 minutes later on caffeine, so watch the clock as well as the cup.","refs":["later_bed"]}]]}'::jsonb)
  on conflict (paper_id, feature_key) do update set payload = excluded.payload, updated_at = now();
insert into public.protocol_steps (id, paper_id, position, label, detail, kind, evidence_grade, source_estimate, target_per_week, counts_step_id, condition_key, condition_value, applies_when, retired_at) values
  ('4c89568a-c91b-58ce-b9af-7a0f80d6331c', '2f0cc739-d18b-5ca3-9981-5971623614e9', 1, 'Last caffeine at least 8 hours before bed', 'The gap this trial tested. It did not test anything shorter.', 'action', 'low', 'Total sleep time, time to fall asleep and sleep stages: no significant difference from placebo (p > 0.05); the text reports no effect size', null, null, null, null, null, null),
  ('2a1328ac-dcb7-5ff1-9f9a-489cc00ee384', '2f0cc739-d18b-5ca3-9981-5971623614e9', 2, 'In bed within 30 minutes of my usual time', 'Participants were asked to keep to this at home. The trial did not test it, so it carries no weight.', 'action', 'none', null, null, null, null, null, null, null)
  on conflict (id) do update set position = excluded.position, label = excluded.label, detail = excluded.detail, kind = excluded.kind,
    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;

-- hiit-body-composition
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('8d1309b7-9fbb-592d-93ae-8ff9a08e6ef6', 'hiit-body-composition', 'Interval training''s best-supported effect is on lean mass, not fat: thirty-six trials, graded', '10.3390/jcm12062291', 'Body composition', 'Across thirty-six randomized trials in adults, interval training reduced body fat percentage by 1.53 points and raised fat-free mass by 0.51 kg. The fat result is graded low certainty. The lean-mass result is graded high, and it hangs on a single trial.', 'premium', '2026-11-12T00:00:00Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('8d1309b7-9fbb-592d-93ae-8ff9a08e6ef6', '{"hook":[{"text":"Interval training is sold on fat loss.","refs":[]},{"text":"Pool the trials, rate how far each result can be trusted, and the order flips.","refs":["grade_ffm","grade_bf"]}],"populationPanel":[{"text":"Who was studied: 1,130 adults with a mean age of 26.27 years, across thirty-six randomized trials lasting 3 to 15 weeks.","refs":["sample","trials"]},{"text":"Most were inactive and overweight or obese, so the findings describe that group best.","refs":["lim_population"]},{"text":"Children, teenagers and people with a known disease were left out.","refs":["excluded"]}],"sections":[{"id":"found","heading":"What the pooled trials show","paragraphs":[[{"text":"Compared with no exercise, interval training in these adults reduced fat mass by 1.86 kg (95% CI 2.55 to 1.18) and body fat percentage by 1.53 points (95% CI 2.13 to 0.92).","refs":["fm_all","bf_all"]},{"text":"Fat-free mass, the weight of everything in the body that is not fat, went up by 0.51 kg.","refs":["ffm_all"]}],[{"text":"Then the authors rated how far each result can be trusted, using a system called GRADE.","refs":["grade_ffm"]},{"text":"Fat-free mass: high.","refs":["grade_ffm"]},{"text":"Fat mass: moderate.","refs":["grade_fm"]},{"text":"Body fat percentage: low.","refs":["grade_bf"]},{"text":"The body-fat trials disagreed with one another heavily; the fat-free-mass trials did not.","refs":["heterogeneity_bf","ffm_no_het"]}]]},{"id":"lower-bound","heading":"How sure is the lean-mass number?","paragraphs":[[{"text":"The 95% confidence interval for fat-free mass runs from 0.06 kg to 0.95 kg.","refs":["ffm_all"]},{"text":"At its weak end that is 0.06 kg, an amount no bathroom scale would register.","refs":["ffm_all"]},{"text":"High certainty here means the trials agree that the average effect is above zero.","refs":["grade_ffm","ffm_no_het"]},{"text":"It does not mean the effect is big.","refs":[]}]]},{"id":"missed","heading":"What most summaries miss","paragraphs":[[{"text":"Take one trial out of the pool and the lean-mass effect is gone: the estimate becomes 0.46 kg lost, with an interval from 1.38 kg lost to 0.44 kg gained.","refs":["ffm_loo"]},{"text":"So the result graded most certain also rests on a single study.","refs":["ffm_loo","grade_ffm"]}],[{"text":"The second surprise is which kind of training did what.","refs":[]},{"text":"Only cycling raised fat-free mass in these trials, by 0.63 kg (95% CI 0.17 to 1.09).","refs":["ffm_cycling"]},{"text":"Running did not.","refs":["ffm_only_cycling"]},{"text":"Overground running showed the widest drop in body fat percentage, 2.80 points (95% CI 3.89 to 1.71), but that is the low-certainty outcome.","refs":["bf_overground","grade_bf"]},{"text":"Treadmill running did not clearly change fat mass at all: its interval runs from 2.82 kg lost to 0.62 kg gained.","refs":["fm_treadmill"]}]]},{"id":"pattern","heading":"The pattern in the programmes","paragraphs":[[{"text":"Across outcomes the same settings kept landing on the favourable side: more than 8 weeks, three sessions a week, work bursts under 60 seconds, rests of 90 seconds or less, and moving during the rest.","refs":["recipe"]},{"text":"These come from comparing subgroups of trials, not from testing one setting directly against another, so treat them as leads.","refs":["subgroups"]}]]},{"id":"parallel","heading":"A related idea","paragraphs":[[{"text":"The authors note an earlier pooled analysis that found no clear effect of cycling on fat mass in overweight and obese adults.","refs":["wewege"]},{"text":"They also raise a practical point: heavier bodies load the joints differently when running, which is one reason cycling may suit some people better whatever the averages say.","refs":["joints"]}]]}],"limitations":[[{"text":"Most trials enrolled inactive adults who were overweight or obese.","refs":["lim_population"]},{"text":"The results may not carry over to people who already train.","refs":["lim_population"]}],[{"text":"The trials disagreed with each other, most of all on body fat percentage, which is why that result is graded low.","refs":["lim_heterogeneity","grade_bf"]}],[{"text":"Body composition was measured with different tools from trial to trial, from skinfold calipers to DEXA scans.","refs":["lim_methods"]}],[{"text":"The fat-free-mass result disappears when a single trial is removed.","refs":["lim_loo"]}]],"primaryEstimate":"ffm_all","simulator":{"kind":"hiit-forest","params":{"outcomes":[{"id":"ffm","label":"Fat-free mass","better":"up","grade":{"id":"grade_ffm","kind":"grade","label":"GRADE certainty for fat-free mass","quote":"which indicated the effect of FFM to be of high quality"},"overall":{"id":"ffm_all","kind":"estimate","label":"Fat-free mass, all interval training vs control","quote":"HIIT induced an overall significant improvement in FFM (WMD: 0.51 kg, 95% CI: 0.06 to 0.95","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.51,"ciLow":0.06,"ciHigh":0.95,"unit":"kg","absolute":true,"tier":"high"}}},{"id":"fm","label":"Fat mass","better":"down","grade":{"id":"grade_fm","kind":"grade","label":"GRADE certainty for fat mass","quote":"the evidence about FM and BF% was downgraded to medium and low levels, respectively"},"overall":{"id":"fm_all","kind":"estimate","label":"Fat mass, all interval training vs control","quote":"HIIT resulted in a significant reduction in FM (WMD: −1.86 kg, 95% CI: −2.55 to −1.18","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.86,"ciLow":-2.55,"ciHigh":-1.18,"unit":"kg","absolute":true,"tier":"moderate"}}},{"id":"bf","label":"Body fat percentage","better":"down","grade":{"id":"grade_bf","kind":"grade","label":"GRADE certainty for body fat percentage","quote":"the evidence about FM and BF% was downgraded to medium and low levels, respectively"},"overall":{"id":"bf_all","kind":"estimate","label":"Body fat percentage, all interval training vs control","quote":"induced a significant reduction in BF% [weighted mean difference (WMD): −1.53%, 95% CI: −2.13, −0.92","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.53,"ciLow":-2.13,"ciHigh":-0.92,"unit":"points","absolute":true,"tier":"low"}}}],"settings":[{"id":"modality","label":"Type of interval","options":[{"id":"cycling","label":"Cycling","ffm":{"id":"ffm_cycling","kind":"estimate","label":"Fat-free mass, cycling","quote":"only HIIT involving cycling interventions resulted in a significant increase in FFM compared to other exercise modalities (WMD: 0.63 kg, 95% CI: 0.17 to 1.09","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.63,"ciLow":0.17,"ciHigh":1.09,"unit":"kg","absolute":true,"tier":"high"}},"fm":{"id":"fm_cycling","kind":"estimate","label":"Fat mass, cycling","quote":"cycling and overground running reduced FM (WMD: −1.72 kg, 95% CI: −2.41 to −1.30,0.001 and WMD: −4.25 kg, 95% CI: −5.90 to −2.61","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.72,"ciLow":-2.41,"ciHigh":-1.3,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":null},{"id":"overground","label":"Overground running","ffm":null,"fm":{"id":"fm_overground","kind":"estimate","label":"Fat mass, overground running","quote":"cycling and overground running reduced FM (WMD: −1.72 kg, 95% CI: −2.41 to −1.30,0.001 and WMD: −4.25 kg, 95% CI: −5.90 to −2.61","estimate":{"outcome":"Fat mass","measure":"WMD","point":-4.25,"ciLow":-5.9,"ciHigh":-2.61,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_overground","kind":"estimate","label":"Body fat percentage, overground running","quote":"overground running induced the largest overall effect (WMD: −2.80%, 95% CI: −3.89 to −1.71","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-2.8,"ciLow":-3.89,"ciHigh":-1.71,"unit":"points","absolute":true,"tier":"low"}}},{"id":"treadmill","label":"Treadmill running","ffm":null,"fm":{"id":"fm_treadmill","kind":"estimate","label":"Fat mass, treadmill running","quote":"treadmill running did not induce significant changes (WMD: −1.10 kg, 95% CI: −2.82 to 0.62","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.1,"ciLow":-2.82,"ciHigh":0.62,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":null}]},{"id":"weeks","label":"Programme length","options":[{"id":"over8","label":"More than 8 weeks","ffm":{"id":"ffm_over8","kind":"estimate","label":"Fat-free mass, programmes longer than 8 weeks","quote":"produced larger effects than trials of shorter (i.e., less than 8 weeks) durations (WMD: 0.63 kg, 95% CI: 0.17 to 1.10","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.63,"ciLow":0.17,"ciHigh":1.1,"unit":"kg","absolute":true,"tier":"high"}},"fm":{"id":"fm_over8","kind":"estimate","label":"Fat mass, programmes longer than 8 weeks","quote":"a larger effect on FM was noted when compared to shorter (i.e., less than 8 weeks) interventions (WMD: −1.92 kg, 95% CI: −2.35 to −1.50","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.92,"ciLow":-2.35,"ciHigh":-1.5,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_over8","kind":"estimate","label":"Body fat percentage, programmes longer than 8 weeks","quote":"a larger effect on BF% was noted when compared to shorter (i.e., less than 8 weeks) interventions (WMD: −2.08%, 95% CI: −2.40 to −1.76","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-2.08,"ciLow":-2.4,"ciHigh":-1.76,"unit":"points","absolute":true,"tier":"low"}}},{"id":"upto8","label":"8 weeks or less","ffm":null,"fm":null,"bf":null}]},{"id":"frequency","label":"Sessions a week","options":[{"id":"three","label":"Three","ffm":{"id":"ffm_3wk","kind":"estimate","label":"Fat-free mass, 3 sessions a week","quote":"3 sessions per week induced a significant increase in FFM (WMD: 0.50 kg, 95% CI: 0.06 to 0.94","estimate":{"outcome":"Fat-free mass","measure":"WMD","point":0.5,"ciLow":0.06,"ciHigh":0.94,"unit":"kg","absolute":true,"tier":"high"}},"fm":{"id":"fm_3wk","kind":"estimate","label":"Fat mass, 3 sessions a week","quote":"2 and 3 sessions per week had a significant effect on reducing FM (WMD: −4.43 kg, 95% CI: −6.62 to −2.24,0.001 and WMD: −1.24 kg, 95% CI: −2.00 to −0.48","estimate":{"outcome":"Fat mass","measure":"WMD","point":-1.24,"ciLow":-2,"ciHigh":-0.48,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_3wk","kind":"estimate","label":"Body fat percentage, 3 sessions a week","quote":"three sessions per week had a significant effect on reducing BF% (WMD: −1.17%, 95% CI: −1.85 to −0.50,0.001), while two sessions per week were not significant (WMD: −3.23%, 95% CI: −6.52 to 0.04","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-1.17,"ciLow":-1.85,"ciHigh":-0.5,"unit":"points","absolute":true,"tier":"low"}}},{"id":"two","label":"Two","ffm":null,"fm":{"id":"fm_2wk","kind":"estimate","label":"Fat mass, 2 sessions a week","quote":"2 and 3 sessions per week had a significant effect on reducing FM (WMD: −4.43 kg, 95% CI: −6.62 to −2.24,0.001 and WMD: −1.24 kg, 95% CI: −2.00 to −0.48","estimate":{"outcome":"Fat mass","measure":"WMD","point":-4.43,"ciLow":-6.62,"ciHigh":-2.24,"unit":"kg","absolute":true,"tier":"moderate"}},"bf":{"id":"bf_2wk","kind":"estimate","label":"Body fat percentage, 2 sessions a week","quote":"three sessions per week had a significant effect on reducing BF% (WMD: −1.17%, 95% CI: −1.85 to −0.50,0.001), while two sessions per week were not significant (WMD: −3.23%, 95% CI: −6.52 to 0.04","estimate":{"outcome":"Body fat percentage","measure":"WMD","point":-3.23,"ciLow":-6.52,"ciHigh":0.04,"unit":"points","absolute":true,"tier":"low"}}}]},{"id":"work","label":"Each work burst","options":[{"id":"short","label":"60 seconds or less","ffm":{"id":"ffm_le60","kind":"estimate","label":"Fat-free mass, work bursts of 60 s or less","quote":"≤60 s produced a significant increase in FFM (WMD: 0.57 kg, 95% CI: 0.29 to 1.44","estimate":{"outcome":"Fat-free mass","measure":"WM