    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;

-- steps-days-per-week
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('58929ab5-72ec-5a41-941b-be5f29965932', 'steps-days-per-week', '8,000 steps on one or two days a week: what ten years of death records show', '10.1001/jamanetworkopen.2023.5174', 'Movement', 'Among 3,101 US adults, reaching 8,000 steps on only 1 to 2 days a week was associated with a 10-year risk of death 14.9 points lower than never reaching it. The comparison is less clean than it sounds.', 'free', '2026-11-12T00:00:00Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('58929ab5-72ec-5a41-941b-be5f29965932', '{"hook":[{"text":"Step counts are usually sold as a daily target.","refs":[]},{"text":"This study asked a different question: does it matter on how many days of the week you get there?","refs":["threshold"]}],"populationPanel":[{"text":"Who was studied: 3,101 US adults aged 20 or older who wore an accelerometer for 1 week in 2005-2006 and were then traced through national death records.","refs":["sample","cohort"]},{"text":"Nobody was assigned to walk more or less, so this is an observational study.","refs":["cohort"]},{"text":"It describes these adults. It is not a prescription.","refs":[]}],"sections":[{"id":"found","heading":"What they found","paragraphs":[[{"text":"Researchers sorted people by how many days that week they reached 8,000 steps: none, 1 to 2 days, or 3 to 7 days.","refs":["threshold"]},{"text":"Within 10 years, 40.7% of the people with no such days had died, against 14.1% of those with 1 to 2 days and 5.5% of those with 3 to 7.","refs":["followup","threshold","crude_0","crude_1_2","crude_3_7"]}],[{"text":"Those raw figures flatter walking, because the three groups were very different people.","refs":[]},{"text":"After the researchers accounted for age, sex, smoking, existing illness and average daily steps, the 1-to-2-day group still had a 10-year risk of death 14.9 points lower than the zero-day group.","refs":["ard_1_2","followup","models"]},{"text":"For 3 to 7 days the figure was 16.5 points.","refs":["ard_3_7"]},{"text":"That is only a little more, and the curve went flat at 3 to 4 days.","refs":["plateau"]}]]},{"id":"lower-bound","heading":"How sure is that number?","paragraphs":[[{"text":"The 95% confidence interval for the 1-to-2-day group runs from 18.8 points down to 10.9 points.","refs":["ard_1_2"]},{"text":"So even the weakest reading that fits the data is a 10.9-point gap, which is wide for a study of deaths.","refs":["ard_1_2"]},{"text":"What the interval cannot tell you is whether the walking is the reason for the gap.","refs":[]}]]},{"id":"missed","heading":"What most summaries miss","paragraphs":[[{"text":"The zero-day group had a mean age of 63.7.","refs":["ages"]},{"text":"The 3-to-7-day group had a mean age of 46.0.","refs":["ages","threshold"]},{"text":"Half of the zero-day group, 50.5%, said they had difficulty walking 0.25 miles or climbing 10 stairs, against 6.8% of the most active group.","refs":["mobility","mobility_def"]}],[{"text":"People who are already unwell walk less and die sooner, so part of the gap is illness, not walking.","refs":["confounding"]},{"text":"The authors adjusted for this and say plainly that some of it remains.","refs":["confounding"]}],[{"text":"One more detail: the gap was 7.4 points in adults under 65 and 19.9 points in those 65 and over.","refs":["ard_1_2_under65","ard_1_2_65plus"]}]]},{"id":"parallel","heading":"A related idea","paragraphs":[[{"text":"The authors point to an earlier pooled analysis in which risk stopped falling at 6,000 to 8,000 steps a day for adults over 60, and at 8,000 to 10,000 for younger adults.","refs":["parallel_meta"]},{"text":"Both findings describe the same shape from two directions: steep at the bottom, flat at the top.","refs":["parallel_meta","plateau"]}],[{"text":"Moving the daily threshold anywhere between 6,000 and 10,000 steps gave similar results, so 8,000 is a convenient marker, not a magic line.","refs":["thresholds","threshold"]}]]}],"limitations":[[{"text":"Steps were measured for only 1 week, at the start.","refs":["one_week"]},{"text":"How these people walked over the following 10 years is unknown.","refs":["one_week","followup"]}],[{"text":"This is an observational study.","refs":["cohort"]},{"text":"People in poor health walk less and are more likely to die, and no adjustment removes that completely.","refs":["confounding"]}],[{"text":"Wearing a tracker can make people more active for that week, which would place some usually inactive people in the wrong group.","refs":["hawthorne"]}]],"primaryEstimate":"ard_1_2","simulator":{"kind":"steps-days","params":{"threshold":{"n":8000,"ref":"threshold"},"followupYears":{"n":10,"ref":"followup"},"groups":[{"id":"g0","label":"No days","from":{"n":0,"ref":"threshold"},"to":{"n":0,"ref":"threshold"},"meanAge":{"n":63.7,"ref":"ages"}},{"id":"g1","label":"1 to 2 days","from":{"n":1,"ref":"threshold"},"to":{"n":2,"ref":"threshold"},"meanAge":{"n":51.5,"ref":"ages"}},{"id":"g2","label":"3 to 7 days","from":{"n":3,"ref":"threshold"},"to":{"n":7,"ref":"threshold"},"meanAge":{"n":46,"ref":"ages"}}],"outcomes":[{"id":"all","label":"Death from any cause","crude":{"g0":{"id":"crude_0","kind":"estimate","label":"Share of the 0-day group who died within 10 years, unadjusted","quote":"257/632 (40.7)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":40.7,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"g1":{"id":"crude_1_2","kind":"estimate","label":"Share of the 1-2-day group who died within 10 years, unadjusted","quote":"75/532 (14.1)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":14.1,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"g2":{"id":"crude_3_7","kind":"estimate","label":"Share of the 3-7-day group who died within 10 years, unadjusted","quote":"107/1937 (5.5)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":5.5,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}}},"models":[{"id":"agesex","label":"Age and sex","g1":{"id":"ard_1_2_agesex","kind":"estimate","label":"Risk difference adjusted for age and sex only, 1-2 days, all-cause","quote":"−18.7 (−23.2 to −14.4)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-18.7,"ciLow":-23.2,"ciHigh":-14.4,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"ard_3_7_agesex","kind":"estimate","label":"Risk difference adjusted for age and sex only, 3-7 days, all-cause","quote":"−23.0 (−26.8 to −19.3)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-23,"ciLow":-26.8,"ciHigh":-19.3,"unit":"points","absolute":true,"tier":"low"}}},{"id":"m1","label":"Plus health and lifestyle","g1":{"id":"ard_1_2_m1","kind":"estimate","label":"Risk difference, model 1 (demographics, health, lifestyle), 1-2 days, all-cause","quote":"−15.9 (−20.0 to −11.8)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-15.9,"ciLow":-20,"ciHigh":-11.8,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"ard_3_7_m1","kind":"estimate","label":"Risk difference, model 1, 3-7 days, all-cause","quote":"−19.4 (−23.0 to −15.8)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-19.4,"ciLow":-23,"ciHigh":-15.8,"unit":"points","absolute":true,"tier":"low"}}},{"id":"m2","label":"Plus average daily steps","g1":{"id":"ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days vs 0 days, all-cause","quote":"all-cause mortality risk was lower among those who took 8000 steps or more 1 to 2 days per week (aRD, −14.9%; 95% CI −18.8% to −10.9%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-14.9,"ciLow":-18.8,"ciHigh":-10.9,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days vs 0 days, all-cause","quote":"3 to 7 days per week (aRD, −16.5%; 95% CI, −20.4% to −12.5%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-16.5,"ciLow":-20.4,"ciHigh":-12.5,"unit":"points","absolute":true,"tier":"low"}}}]},{"id":"cv","label":"Cardiovascular death","crude":{"g0":{"id":"cv_crude_0","kind":"estimate","label":"Share of the 0-day group who died of cardiovascular disease, unadjusted","quote":"87/462 (18.8)","estimate":{"outcome":"Cardiovascular deaths within 10 years, unadjusted","measure":"proportion","point":18.8,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"g1":{"id":"cv_crude_1_2","kind":"estimate","label":"Share of the 1-2-day group who died of cardiovascular disease, unadjusted","quote":"26/483 (5.4)","estimate":{"outcome":"Cardiovascular deaths within 10 years, unadjusted","measure":"proportion","point":5.4,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"g2":{"id":"cv_crude_3_7","kind":"estimate","label":"Share of the 3-7-day group who died of cardiovascular disease, unadjusted","quote":"35/1865 (1.9)","estimate":{"outcome":"Cardiovascular deaths within 10 years, unadjusted","measure":"proportion","point":1.9,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}}},"models":[{"id":"agesex","label":"Age and sex","g1":{"id":"cv_ard_1_2_agesex","kind":"estimate","label":"Risk difference adjusted for age and sex only, 1-2 days, cardiovascular","quote":"−9.6 (−12.9 to −6.3)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-9.6,"ciLow":-12.9,"ciHigh":-6.3,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"cv_ard_3_7_agesex","kind":"estimate","label":"Risk difference adjusted for age and sex only, 3-7 days, cardiovascular","quote":"−11.1 (−14.4 to −7.9)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-11.1,"ciLow":-14.4,"ciHigh":-7.9,"unit":"points","absolute":true,"tier":"low"}}},{"id":"m1","label":"Plus health and lifestyle","g1":{"id":"cv_ard_1_2_m1","kind":"estimate","label":"Risk difference, model 1, 1-2 days, cardiovascular","quote":"−8.5 (−12.2 to −4.9)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-8.5,"ciLow":-12.2,"ciHigh":-4.9,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"cv_ard_3_7_m1","kind":"estimate","label":"Risk difference, model 1, 3-7 days, cardiovascular","quote":"−9.8 (−13.4 to −6.2)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-9.8,"ciLow":-13.4,"ciHigh":-6.2,"unit":"points","absolute":true,"tier":"low"}}},{"id":"m2","label":"Plus average daily steps","g1":{"id":"cv_ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days, cardiovascular","quote":"(aRD, −8.1%; 95% CI, −11.8% to −4.4%)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-8.1,"ciLow":-11.8,"ciHigh":-4.4,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"cv_ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days, cardiovascular","quote":"(aRD, −8.4%; 95% CI, −12.5% to −4.4%)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-8.4,"ciLow":-12.5,"ciHigh":-4.4,"unit":"points","absolute":true,"tier":"low"}}}]}],"modelNote":{"id":"models","kind":"context","label":"What each adjustment model added","quote":"Model 1 included age; sex; race and ethnicity; insurance status; marital status; smoking; body mass index; estimated glomerular filtration rate; statin use; and history of diabetes, hypertension, cardiovascular disease, cancer, and emphysema. Model 2 included average daily step counts in addition to the covariates in model 1."}}},"facts":{"ages":{"id":"ages","kind":"statement","label":"Mean age of the three groups (0, 1-2, 3-7 days)","quote":"Age, mean (SD), y\n\n63.7 (19.3)\n\n51.5 (19.0)\n\n46.0 (15.5)"},"ard_1_2":{"id":"ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days vs 0 days, all-cause","quote":"all-cause mortality risk was lower among those who took 8000 steps or more 1 to 2 days per week (aRD, −14.9%; 95% CI −18.8% to −10.9%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-14.9,"ciLow":-18.8,"ciHigh":-10.9,"unit":"points","absolute":true,"tier":"low"}},"ard_1_2_65plus":{"id":"ard_1_2_65plus","kind":"estimate","label":"Adjusted risk difference, 1-2 days, adults 65 and over","quote":"aged ≥65 years: aRD, −19.9% [95% CI, −30.8% to −8.9%]","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-19.9,"ciLow":-30.8,"ciHigh":-8.9,"unit":"points","absolute":true,"tier":"low"}},"ard_1_2_under65":{"id":"ard_1_2_under65","kind":"estimate","label":"Adjusted risk difference, 1-2 days, adults under 65","quote":"aged <65 years: aRD, −7.4% [95% CI, −11.2% to −3.7%]","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-7.4,"ciLow":-11.2,"ciHigh":-3.7,"unit":"points","absolute":true,"tier":"low"}},"ard_3_7":{"id":"ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days vs 0 days, all-cause","quote":"3 to 7 days per week (aRD, −16.5%; 95% CI, −20.4% to −12.5%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-16.5,"ciLow":-20.4,"ciHigh":-12.5,"unit":"points","absolute":true,"tier":"low"}},"cohort":{"id":"cohort","kind":"context","label":"Who was enrolled, when, and how steps were measured","quote":"This cohort study evaluated a representative sample of participants aged 20 years or older in the National Health and Nutrition Examination Surveys 2005-2006 who wore an accelerometer for 1 week and their mortality data through December 31, 2019."},"confounding":{"id":"confounding","kind":"limitation","label":"Residual confounding by health status","quote":"our findings still have residual confounding bias (ie, poor health could influence daily step counts and mortality risk)"},"crude_0":{"id":"crude_0","kind":"estimate","label":"Share of the 0-day group who died within 10 years, unadjusted","quote":"257/632 (40.7)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":40.7,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"crude_1_2":{"id":"crude_1_2","kind":"estimate","label":"Share of the 1-2-day group who died within 10 years, unadjusted","quote":"75/532 (14.1)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":14.1,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"crude_3_7":{"id":"crude_3_7","kind":"estimate","label":"Share of the 3-7-day group who died within 10 years, unadjusted","quote":"107/1937 (5.5)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":5.5,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"followup":{"id":"followup","kind":"context","label":"Length of follow-up and number of deaths","quote":"Over the 10-year follow-up, all-cause and cardiovascular deaths occurred in 439 (14.2%) and 148 (5.3%) participants, respectively."},"hawthorne":{"id":"hawthorne","kind":"limitation","label":"People may walk more because they are wearing a tracker","quote":"as a result of knowledge that they are wearing the device, participants might have a tendency to be more active, a phenomenon known as the Hawthorne effect"},"mobility":{"id":"mobility","kind":"statement","label":"Number (%) with a mobility limitation in the three groups","quote":"Mobility limitation\n\n319 (50.5)\n\n108 (20.3)\n\n132 (6.8)"},"mobility_def":{"id":"mobility_def","kind":"context","label":"How mobility limitation was defined","quote":"Mobility limitations were defined as self-report of difficulty walking 0.25 miles without special equipment or climbing 10 stairs."},"models":{"id":"models","kind":"context","label":"What each adjustment model added","quote":"Model 1 included age; sex; race and ethnicity; insurance status; marital status; smoking; body mass index; estimated glomerular filtration rate; statin use; and history of diabetes, hypertension, cardiovascular disease, cancer, and emphysema. Model 2 included average daily step counts in addition to the covariates in model 1."},"one_week":{"id":"one_week","kind":"limitation","label":"Steps measured for a single week","quote":"because daily steps were only measured for 1 week at baseline, we did not have information on how changes in physical activity contribute to risk of mortality"},"parallel_meta":{"id":"parallel_meta","kind":"context","label":"Earlier meta-analysis on steps per day and mortality, cited by the authors","quote":"a recent meta-analysis showed decreasing mortality risks with an increasing number of daily steps until 6000 to 8000 steps are reached for adults older than 60 years and at 8000 to 10 000 steps per day for those younger than 60 years"},"plateau":{"id":"plateau","kind":"statement","label":"Where the curve flattened","quote":"the risk of mortality at 10 years rapidly decreased as the number of days per week taking 8000 steps or more increased and plateaued at 3 to 4 days"},"sample":{"id":"sample","kind":"context","label":"Number of participants","quote":"Among 3101 participants (mean [SD] age, 50.5 [18.4] years"},"threshold":{"id":"threshold","kind":"context","label":"How participants were grouped","quote":"Participants were grouped by the number of days per week they took 8000 steps or more (0 days, 1-2 days, and 3-7 days)."},"thresholds":{"id":"thresholds","kind":"statement","label":"Other step thresholds gave similar results","quote":"Different thresholds for the number of daily steps between 6000 and 10 000 yielded similar results."}}}'::jsonb)
  on conflict (paper_id) do update set content_json = excluded.content_json, updated_at = now();
insert into public.paper_feature_content (paper_id, feature_key, payload) values ('58929ab5-72ec-5a41-941b-be5f29965932', 'key_takeaways', '{"takeaways":[[{"text":"If a daily target keeps failing, the study''s lowest active group is a reasonable place to start: 8,000 steps on 1 to 2 days a week.","refs":["threshold","ard_1_2"]}],[{"text":"Past 3 to 4 such days the association flattened, so a missed day is no reason to write off the week.","refs":["plateau"]}],[{"text":"The association was widest in adults aged 65 and over, at 19.9 points against 7.4 points in younger adults.","refs":["ard_1_2_65plus","ard_1_2_under65"]}]]}'::jsonb)
  on conflict (paper_id, feature_key) do update set payload = excluded.payload, updated_at = now();
insert into public.protocol_steps (id, paper_id, position, label, detail, kind, evidence_grade, source_estimate, target_per_week, counts_step_id, condition_key, condition_value, applies_when, retired_at) values
  ('cd120d77-53a2-59fd-8bef-41a28b033ee7', '58929ab5-72ec-5a41-941b-be5f29965932', 1, 'Reached 8,000 steps today', 'Tick on any day your tracker shows 8,000 or more. A log, not a daily requirement.', 'action', 'none', null, null, null, null, null, null, null),
