  ('8ae27155-81be-5408-9d91-309329f4f1f0', '58929ab5-72ec-5a41-941b-be5f29965932', 3, '8,000 steps on at least 3 days this week', 'The study''s 3-to-7-day group, where the association went flat.', 'weekly_target', 'low', '10-year risk of death from any cause −16.5 points (95% CI −20.4 to −12.5)', 3, 'cd120d77-53a2-59fd-8bef-41a28b033ee7', null, null, null, null)
  on conflict (id) do update set position = excluded.position, label = excluded.label, detail = excluded.detail, kind = excluded.kind,
